// ================= перетаскивание (Pointer Events, самодостаточно) =================
function ulInit(uls) {
  uls.forEach(ul => {
    ul.addEventListener("pointerdown", (e) => {
      const li = e.target && e.target.closest ? e.target.closest(".trait") : null;
      if (!li || !ul.contains(li)) return;
      if (e.button !== undefined && e.button !== 0) return;
      startDrag(ul, li, e);
    });
  });
}

function startDrag(ul, li, startEvt) {
  const liRect = li.getBoundingClientRect();
  const liH = liRect.height;
  const gap = 8; // = gap в CSS
  const cell = liH + gap;
  const startTop = liRect.top;
  const grabOffset = startEvt.clientY - startTop; // смещение курсора от верхнего края
  let dragging = false;

  const move = (ev) => {
    if (!dragging && Math.hypot(ev.clientX - startEvt.clientX, ev.clientY - startEvt.clientY) < 5) return;
    if (!dragging) {
      dragging = true;
      li.classList.add("is-lifted");
    }
    ev.preventDefault();

    // «абсолютная» верхняя позиция, которой соответствует текущий cursor
    // независимо от перестановок: отталкиваемся от startTop
    const desiredTop = ev.clientY - grabOffset;
    const desiredIdx = Math.max(0, Math.min(3, Math.round((desiredTop - ulTop()) / cell)));

    const curIdx = Array.prototype.indexOf.call(ul.children, li);
    if (desiredIdx !== curIdx) {
      commitReorder(ul, li, desiredIdx);
    }

    // визуальное смещение относительно «естественного» положения
    li.style.transform = "translateY(" + (desiredTop - ulTop() - curIdx * cell) + "px)";
  };

