  function ulTop() {
    const ulRect = ul.getBoundingClientRect();
    return ulRect.top;
  }

  const up = (ev) => {
    if (!dragging) { // простой клик — фокусируем
      li.focus({ preventScroll: true });
    }
    li.classList.remove("is-lifted");
    li.style.transform = "";
    ul.querySelectorAll(".trait.is-hint").forEach(x => x.classList.remove("is-hint"));
    if (dragging) {
      syncFromDOM(ul); // фиксируем состояние из DOM
      paintRanks(ul);
    }
    remove();
  };

  const remove = () => {
    window.removeEventListener("pointermove", move);
    window.removeEventListener("pointerup", up);
    window.removeEventListener("pointercancel", up);
  };

  window.addEventListener("pointermove", move, { passive: false });
  window.addEventListener("pointerup", up);
  window.addEventListener("pointercancel", up);

  // не даём браузеру тапать страницу во время перетаскивания
  if (li.setPointerCapture) {
    try { li.setPointerCapture(startEvt.pointerId); } catch (_) {}
  }
}

