import { chromium } from 'playwright';

const url = 'file://' + process.argv[2];
const browser = await chromium.launch({
  channel: 'chromium',
  args: ['--no-sandbox', '--allow-file-access-from-files'],
  headless: 'new',
});
const page = await browser.newPage({ viewport: { width: 1200, height: 900 } });
page.on('pageerror', e => console.log('PAGE ERROR:', e.message));
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE ERROR:', m.text()); });

await page.goto(url, { waitUntil: 'load' });
await page.waitForTimeout(300);

const errors = [];

// 1) count questions
const listCount = await page.locator('ul.trait-list').count();
console.log('list count:', listCount);
if (listCount !== 24) errors.push('expected 24 lists, got ' + listCount);

// 2) extract data (per list: text + type) and compare to reference
const data = await page.evaluate(() => {
  const out = [];
  document.querySelectorAll('ul.trait-list').forEach((ul) => {
    const list = [];
    ul.querySelectorAll('li.trait').forEach((li) => {
      const text = li.querySelector('.label').textContent.trim();
      const type = li.dataset.type;
      list.push([text, type]);
    });
    out.push(list);
  });
  return out;
});

const ref = JSON.parse(require('fs').readFileSync(process.argv[3], 'utf8'));
// ref format: we will adapt — read it and normalize
const refFlat = [];
function pushRef(list) { list.forEach(x => refFlat.push(x)); }
if (Array.isArray(ref)) {
  if (Array.isArray(ref[0]) && Array.isArray(ref[0][0])) {
    ref.forEach(l => l.forEach(x => pushRef(x)));
  } else if (Array.isArray(ref[0]) && typeof ref[0][0] === 'string') {
    ref.forEach(x => pushRef([x]));
  } else if (ref[0].text !== undefined) {
    ref.forEach((x) => refFlat.push([x.text, x.type]));
  }
} else if (ref.questions) {
  ref.questions.forEach(q => {
    if (Array.isArray(q.options)) q.options.forEach(o => refFlat.push([o.text, o.type]));
    else if (q.text !== undefined) refFlat.push([q.text, q.type]);
  });
}

const myFlat = [];
data.forEach(l => l.forEach(x => myFlat.push(x)));
console.log('flat counts:', myFlat.length, refFlat.length);

// compare as multisets
const key = (p) => p[0] + '|' + p[1];
const A = myFlat.map(key).sort().join('\n');
const B = refFlat.map(key).sort().join('\n');
if (A !== B) {
  const sa = new Set(A.split('\n')), sb = new Set(B.split('\n'));
  const onlyMine = [...sa].filter(x => !sb.has(x));
  const onlyRef = [...sb].filter(x => !sa.has(x));
  console.log('MISMATCH');
  console.log('only-in-mine (up to 10):', onlyMine.slice(0, 10));
  console.log('only-in-ref (up to 10):', onlyRef.slice(0, 10));
} else {
  console.log('DATA MATCH OK');
}

// 3) simulate a drag: from position 0 to position 3 on list 1, check data and rank labels
const firstList = page.locator('ul.trait-list').first();
const firstItem = firstList.locator('li.trait').first();
const firstRect = await firstItem.boundingBox();
const thirdRect = await firstList.locator('li.trait').nth(3).boundingBox();
await page.mouse.move(firstRect.x + 100, firstRect.y + firstRect.height / 2);
await page.mouse.down();
await page.mouse.move(firstRect.x + 100, (thirdRect.y + thirdRect.height / 2), { steps: 40 });
await page.mouse.up();
