// Minimal CDP driver over WebSocket (no deps) against the bundled Chrome.
import { spawn } from 'node:child_process';
import fs from 'node:fs';
import http from 'node:http';
import url from 'node:url';

const CHROME = process.env.CHROME_BIN ||
  '/home/dp/.cache/puppeteer/chrome/linux-157.0.8103.50/chrome-linux64/chrome';

function getJSON(u) {
  return new Promise((res, rej) => {
    http.get(u, (r) => {
      let s = '';
      r.on('data', c => s += c);
      r.on('end', () => res(JSON.parse(s)));
    }).on('error', rej);
  });
}

// tiny WS client (just enough for CDP: text frames, no extensions)
import net from 'node:net';
import tls from 'node:tls';
import crypto from 'node:crypto';

function wsConnect(u, cb, err) {
  const u2 = new URL(u);
  const sock = tls.connect({ host: u2.hostname, port: u2.port || 443, servername: u2.hostname, rejectUnauthorized: false }, () => {
    // HTTP upgrade
    const key = 'dGhpcyBpcyBhIGtleQ==';
    const path = decodeURIComponent(u2.pathname) + u2.search;
    const req =
      'GET ' + path + ' HTTP/1.1\r\n' +
      'Host: ' + u2.host + '\r\n' +
      'Upgrade: websocket\r\n' +
      'Connection: Upgrade\r\n' +
      'Sec-WebSocket-Key: ' + key + '\r\n' +
      'Sec-WebSocket-Version: 13\r\n\r\n';
    sock.write(req);
    const onData = (buf) => {
      let i = 0;
      while (i < buf.length) {
        if (buf[i] === 0) { // FIN+text
          const len = buf[i + 1] & 0x7f;
          if (len < 126) {
            cb(buf.slice(i + 2, i + 2 + len).toString('utf8'));
            i += 2 + len;
          } else if (len === 126) {
            const l = buf.readUInt16BE(i + 2);
            cb(buf.slice(i + 4, i + 4 + l).toString('utf8'));
            i += 4 + l;
          } else {
            cb(buf.slice(i + 10).toString('utf8'));
            break;
          }
        } else { i++; }
      }
    };
    let headerDone = false;
    const origOnData = sod => {
      if (!headerDone) {
        const s = sod.toString('latin1');
        const idx = s.indexOf('\r\n\r\n');
        if (idx === -1) return;
        headerDone = true;
        // rest of the buffer after headers
        const rest = sod.subarray(idx + 4);
        if (rest.length) onData(rest);
        return;
      }
      onData(sod);
    };
    sock.removeAllListeners('data');
    sock.on('data', origOnData);
  });
  sock.on('error', err);
  return sock;
}

function wsSend(sock, obj) {
  const p = Buffer.from(JSON.stringify(obj), 'utf8');
  let header;
  if (p.length < 126) header = Buffer.from([0x81, 0x80 + p.length]);
  else if (p.length < 65536) {
    header = Buffer.alloc(4);
    header[0] = 0x81; header[1] = 0x80 + 126;
    header.writeUInt16BE(p.length, 2);
  } else {
    header = Buffer.alloc(10);
    header[0] = 0x81; header[1] = 0x80 + 127;
    header.writeBigUInt64BE(BigInt(p.length), 2);
  }
  sock.write(Buffer.concat([header, p]));
}

async function connectCDP(port, targetId) {
  const targets = await getJSON(`http://127.0.0.1:${port}/json`);
  const t = targets.find(x => x.id === targetId) || targets[0];
  return new Promise((resolve, reject) => {
    const sock = wsConnect(t.webSocketDebuggerUrl, (msg) => {
      const m = JSON.parse(msg);
      if (m.id !== undefined) {
        const pend = pendings.get(m.id);
        if (pend) {
          pendings.delete(m.id);
          if (m.error) pend.reject(new Error(JSON.stringify(m.error)));
          else pend.resolve(m.result);
        }
      }
    }, reject);
    sock.on('open', () => {});
    // wait until we get the upgrade ack: we'll send a noop to test
    setTimeout(() => { if (!sock.destroyed) resolve({ sock, send }); else reject(new Error('timeout')); }, 250);
    let idc = 0;
    const pendings = new Map();
    function send(method, params = {}) {
      const id = ++idc;
      return new Promise((res, rej) => {
        pendings.set(id, { resolve: res, reject: rej });
        wsSend(sock, { id, method, params });
      });
    }
    // also wire sock 'error' — we passed err in wsConnect. Done.
  });
}

const fileUrl = url.pathToFileURL(process.argv[2]).href;
const outFile = process.argv[3] || 'smoke-report.txt';
const refPath = process.argv[4];

const chrome = spawn(CHROME, [
  '--headless=new',
  '--no-sandbox',
  '--disable-gpu',
  '--remote-debugging-port=9345',
  '--no-first-run',
  '--no-default-browser-check',
  '--allow-file-access-from-files',
  'about:blank',
], { stdio: 'ignore' });

let ws;
async function main() {
  // wait for devtools
  let ok = false;
  for (let i = 0; i < 40 && !ok; i++) {
    await new Promise(r => setTimeout(r, 250));
    try {
      await getJSON('http://127.0.0.1:9345/json');
      ok = true;
    } catch (_) {}
  }
  if (!ok) throw new Error('chrome did not open devtools');
  ws = await connectCDP(9345, null);
  const S = { ...ws };

  await S.send('Runtime.enable');
  await S.send('Page.enable');
  await S.send('Runtime.addBinding', { name: '__done' });
  const nav = await S.send('Page.navigate', { url: fileUrl });
  if (nav.error !== undefined) throw new Error('nav error: ' + JSON.stringify(nav.error));

  const logs = [];
  // we can't easily subscribe to events with this minimal client; re-use polling
  await sleep(600);

  const runJS = async (expression, awaitPromise = false) => {
    const r = await S.send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise });
    if (r.exceptionDetails) {
      throw new Error('js exception: ' + JSON.stringify(r.exceptionDetails.exception.description || r.exceptionDetails.text));
    }
    return r.result.value;
  };

  // 1) data check
  const data = await runJS(`(() => {
    const out = [];
    document.querySelectorAll('ul.trait-list').forEach(ul => {
      const l = [];
      ul.querySelectorAll('li.trait').forEach(li => l.push([li.querySelector('.label').textContent.trim(), li.dataset.type]));
      out.push(l);
    });
    return JSON.stringify(out);
  })()`);
  const mine = JSON.parse(data);
  const ref = JSON.parse(fs.readFileSync(refPath, 'utf8')).flat();
  const key = (p) => p[0] + '|' + p[1];
  const A = mine.flat().map(key).sort().join('\n');
  const B = ref.map(key).sort().join('\n');
  logs.push('lists=' + mine.length + ' flat=' + mine.flat().length + '/' + ref.length);
  if (A !== B) {
    const sa = new Set(A.split('\n')), sb = new Set(B.split('\n'));
    logs.push('only-in-mine: ' + [...sa].filter(x => !sb.has(x)).slice(0, 8).join('; '));
    logs.push('only-in-ref:  ' + [...sb].filter(x => !sa.has(x)).slice(0, 8).join('; '));
    logs.push('DATA MISMATCH');
  } else logs.push('DATA MATCH OK');

  // 2) navigate to step 8 (no drag yet) and check state via DOM
  // 2a) drag first item of list 1 from pos 0 to pos 3 using CDP Input.dispatchMouseEvent
  const rect = await runJS(`(() => {
    const ul = document.querySelector('ul.trait-list');
    const li0 = ul.querySelector('li.trait');
    const li3 = ul.querySelectorAll('li.trait')[3];
    const r0 = li0.getBoundingClientRect();
    const r3 = li3.getBoundingClientRect();
    return JSON.stringify({
      startX: Math.round(r0.x + 80), startY: Math.round(r0.y + r0.height / 2),
      endX: Math.round(r3.x + 80), endY: Math.round(r3.y + r3.height / 2),
    });
  })()`);
  const rr = JSON.parse(rect);
  const mouse = async (type, x, y) =>
    S.send('Input.dispatchMouseEvent', { type, x, y, button: type === 'mouseMove' ? 'none' : 'left', clickCount: type === 'mousePressed' || type === 'mouseReleased' ? 1 : 0 });
  await mouse('mouseMoved', rr.startX, rr.startY);
  await mouse('mousePressed', rr.startX, rr.startY);
  const steps = 20;
  for (let i = 1; i <= steps; i++) {
    await mouse('mouseMoved',
      rr.startX + (rr.endX - rr.startX) * i / steps,
      rr.startY + (rr.endY - rr.startY) * i / steps);
  }
  await mouse('mouseReleased', rr.endX, rr.endY);
  await sleep(150);
  const afterDrag = await runJS(`(() => {
    const ul = document.querySelector('ul.trait-list');
    return JSON.stringify([...ul.querySelectorAll('li.trait')].map(li => [li.querySelector('.label').textContent.trim(), li.dataset.type, li.querySelector('.rank').textContent.trim()]));
  })()`);
  logs.push('after-drag list1: ' + afterDrag);

  // 3) click 'Далее' 7 times
  for (let i = 0; i < 7; i++) {
    await runJS(`document.querySelector('#btnNext').click()`);
    await sleep(40);
  }
  const step8 = await runJS(`(() => {
    const finish = document.querySelector('#btnFinish');
    return JSON.stringify({ finishHidden: finish.hidden, progress: document.querySelector('#progressBar').style.width });
  })()`);
  logs.push('step8: ' + step8);
  await S.send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: true })
    .then(r => fs.writeFileSync('smoke-step8.png', Buffer.from(r.data, 'base64')));

  // 4) click finish
  await runJS(`document.querySelector('#btnFinish').click()`);
  await sleep(150);
  const res = await runJS(`(() => {
    const out = {};
    document.querySelectorAll('#resultview .score').forEach(s => {
      out[s.querySelector('.letter').textContent.trim()] = s.querySelector('.val').textContent.trim();
    });
    return JSON.stringify({
      visible: document.querySelector('#resultview').classList.contains('is-active'),
      testviewHidden: document.querySelector('#testview').style.display === 'none',
      scores: out,
      top: document.querySelector('#resultview .score.is-top')?.querySelector('.letter')?.textContent.trim() || null
    });
  })()`);
  logs.push('result: ' + res);
  await S.send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: true })
    .then(r => fs.writeFileSync('smoke-result.png', Buffer.from(r.data, 'base64')));

